ss="n-old">190</th><th class="n-new">146</th><th class="sign eq"> </th><td class="new"></td></tr></tbody><tbody class="change change-rep"><tr data-type="-"><th class="n-old">191</th><th></th><th class="sign del">-</th><td class="old">    &lt;ul data-type="list-body"&gt;</td></tr><tr data-type="-"><th class="n-old">192</th><th></th><th class="sign del">-</th><td class="old">        &lt;li&gt;&lt;strong&gt;Компост&lt;/strong&gt; — универсальный вариант, вносится ежегодно, 1–2 ведра на м²,&lt;/li&gt;</td></tr><tr data-type="-"><th class="n-old">193</th><th></th><th class="sign del">-</th><td class="old">        &lt;li&gt;&lt;strong&gt;Перепревший навоз&lt;/strong&gt; — один из лучших структурообразователей, насыщает почву органикой,</td></tr><tr data-type="-"><th class="n-old">194</th><th></th><th class="sign del">-</th><td class="old">        &lt;/li&gt;</td></tr><tr data-type="-"><th class="n-old">195</th><th></th><th class="sign del">-</th><td class="old">        &lt;li&gt;&lt;strong&gt;Лежалые опилки&lt;/strong&gt; — свежие использовать нельзя: выделяют смолы и потребляют азот; лежалые</td></tr><tr data-type="-"><th class="n-old">196</th><th></th><th class="sign del">-</th><td class="old">            — хорошо разрыхляют,&lt;/li&gt;</td></tr><tr data-type="-"><th class="n-old">197</th><th></th><th class="sign del">-</th><td class="old">        &lt;li&gt;&lt;strong&gt;Измельчённые ветки и листья&lt;/strong&gt; — отличное сырьё для мульчи и компоста.&lt;/li&gt;</td></tr><tr data-type="-"><th class="n-old">198</th><th></th><th class="sign del">-</th><td class="old">    &lt;/ul&gt;</td></tr><tr data-type="+"><th></th><th class="n-new">147</th><th class="sign ins">+</th><td class="new">&lt;ul data-type="list-body"&gt;</td></tr><tr data-type="+"><th></th><th class="n-new">148</th><th class="sign ins">+</th><td class="new">    &lt;li&gt;&lt;strong&gt;Компост&lt;/strong&gt; — универсальный вариант, вносится ежегодно, 1–2 ведра на м²,&lt;/li&gt;</td></tr><tr data-